#include <vector>
#include <string>
#include <cmath>

class Bucket;
using BucketPtr = std::shared_ptr<Bucket>;

class Bucket {
public:
    Bucket(std::string name, std::vector<float> hash_points) : name_(std::move(name)), hash_points_(std::move(hash_points)) {}
    std::vector<float> partition_points() const { return hash_points_; }
private:
    std::string name_;
    std::vector<float> hash_points_;
};

std::unique_ptr<std::map<float, BucketPtr>> make_balanced_view_map(int num_buckets, int partitions_per_bucket, std::vector<BucketPtr>& buckets_out) {
    auto partition_map = std::make_unique<std::map<float, BucketPtr>>();
    buckets_out.clear();

    if (num_buckets <= 0 || partitions_per_bucket <= 0) {
        return partition_map;
    }

    const int total_partitions = num_buckets * partitions_per_bucket;
    const float step = 1.0f / total_partitions;

    // Create buckets
    for (int i = 0; i < num_buckets; ++i) {
        std::vector<float> partitions;
        partitions.reserve(partitions_per_bucket);

        // Assign partitions to this bucket
        for (int j = 0; j < partitions_per_bucket; ++j) {
            float point = (i * partitions_per_bucket + j) * step;
            // Ensure the point is in [0, 1)
            if (point >= 1.0f) {
                point = 0.0f;
            }
            partitions.push_back(point);
        }

        // Create bucket and add to buckets_out
        std::string bucket_name = "bucket_" + std::to_string(i);
        auto bucket = std::make_shared<Bucket>(bucket_name, partitions);
        buckets_out.push_back(bucket);

        // Populate the partition map
        for (float point : partitions) {
            (*partition_map)[point] = bucket;
        }
    }

    return partition_map;
}

